const PAYLOAD_VERSION = 1;
const MAX_PAYLOAD_DEPTH = 100;
const NODE_TYPES = new Set([
    "server",
    "client",
    "html",
    "fragment",
]);
export function encodeClientBoundaryChildren(nodes) {
    const payload = { version: PAYLOAD_VERSION, nodes };
    return JSON.stringify(payload);
}
export function parseClientBoundaryChildren(serialized) {
    if (!serialized)
        return [];
    try {
        const payload = JSON.parse(serialized);
        if (!isChildrenPayload(payload))
            return [];
        return payload.nodes;
    }
    catch {
        return [];
    }
}
export async function materializeClientBoundaryChildren(nodes, runtime, resolveClientComponent) {
    return await Promise.all(nodes.map((node) => materializeNode(node, runtime, resolveClientComponent)));
}
async function materializeNode(node, runtime, resolveClientComponent) {
    if (node.type === "html")
        return node.text ?? node.html ?? "";
    const children = await materializeClientBoundaryChildren(node.children ?? [], runtime, resolveClientComponent);
    if (node.type === "fragment" || (node.type === "server" && !node.component)) {
        return runtime.createElement(runtime.Fragment, {}, ...children);
    }
    if (node.type === "server") {
        return runtime.createElement(node.component, node.props ?? {}, ...children);
    }
    const Component = await resolveClientComponent(node.component);
    if (!Component)
        return null;
    return runtime.createElement(Component, node.props ?? {}, ...children);
}
function isChildrenPayload(value) {
    if (!isRecord(value) || value.version !== PAYLOAD_VERSION || !Array.isArray(value.nodes)) {
        return false;
    }
    return value.nodes.every((node) => isRSCNode(node, 0));
}
function isRSCNode(value, depth) {
    if (depth > MAX_PAYLOAD_DEPTH || !isRecord(value) || !NODE_TYPES.has(value.type)) {
        return false;
    }
    if (value.type === "html" && typeof value.html !== "string" && typeof value.text !== "string")
        return false;
    if (value.type === "client" &&
        typeof value.component !== "string")
        return false;
    if (value.type === "server" && value.component !== undefined && typeof value.component !== "string") {
        return false;
    }
    if (value.props !== undefined && !isRecord(value.props))
        return false;
    if (value.children === undefined)
        return true;
    return Array.isArray(value.children) &&
        value.children.every((child) => isRSCNode(child, depth + 1));
}
function isRecord(value) {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}
